(() => {
 let ids=new Set(),user=null,loaded=false,failed=false;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const notice=document.createElement('p');notice.className='commerce-toast';notice.setAttribute('role','status');notice.hidden=true;document.body.append(notice);let timer;
 const say=text=>{notice.textContent=text;notice.hidden=false;clearTimeout(timer);timer=setTimeout(()=>notice.hidden=true,6000);};
 function paint(){document.querySelectorAll('[data-favorite]').forEach(b=>{const saved=ids.has(b.dataset.favorite);b.setAttribute('aria-pressed',String(saved));b.textContent=saved?'♥ Salvo':'♡ Salvar favorito';b.disabled=!loaded;});}
 async function load(){try{const r=await fetch('/api/favorites');if(r.status===401){user=null;ids.clear();loaded=true;failed=false;paint();return;}const d=await r.json();if(!r.ok)throw Error(d.error);user=true;ids=new Set(d.products.map(p=>p.id));loaded=true;failed=false;paint();const list=document.querySelector('#favorites-list');if(list){list.replaceChildren();if(!d.products.length){list.innerHTML='<p>Você ainda não salvou produtos. Toque no coração dos seus favoritos.</p><a class="text-link" href="/#produtos">Explorar a vitrine ↗</a>';return;}list.innerHTML=d.products.map(p=>`<article class="favorite-item">${p.image?`<img src="${esc(p.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<span aria-hidden="true">♡</span>'}<div>${p.available?`<a href="/produto/${encodeURIComponent(p.id)}"><strong>${esc(p.name)}</strong></a><p>${p.stock>0?'Em estoque':'Sem estoque no momento'}</p>`:'<strong>Produto indisponível</strong>'}</div><button type="button" data-remove-favorite="${esc(p.id)}" aria-label="Remover ${esc(p.name)} dos favoritos">Remover</button></article>`).join('');}}catch{loaded=true;failed=true;paint();const list=document.querySelector('#favorites-list');if(list){list.innerHTML='<p>Não foi possível carregar seus favoritos.</p><button type="button" id="retry-favorites">Tentar novamente</button>';list.querySelector('button').onclick=load;}}}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-favorite],[data-remove-favorite]');if(!b)return;if(failed){say('Não foi possível consultar sua conta. Tente novamente.');await load();return;}if(!loaded)return;if(!user){location.assign('/conta?returnTo='+encodeURIComponent(location.pathname+location.search+location.hash));return;}const id=b.dataset.favorite||b.dataset.removeFavorite,remove=!!b.dataset.removeFavorite||ids.has(id);b.disabled=true;try{const r=await fetch('/api/favorites/'+encodeURIComponent(id),{method:remove?'DELETE':'PUT'});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível salvar.');if(remove)ids.delete(id);else ids.add(id);paint();say(remove?'Removido dos favoritos.':'Salvo no seu perfil.');if(document.querySelector('#favorites-list'))await load();}catch(err){say(err.message);b.disabled=false;}});
 document.addEventListener('up:account',()=>load());document.addEventListener('up:products-rendered',paint);load();
})();
